def curate_mocks(put,C,T,TF):
 put('reading-mock-4',[
  C('Dans cet article, l’auteur se propose…','de suggérer des cours de musique aux tout-petits.|de commencer l’apprentissage d’un instrument.|d’associer la musique au développement de l’expression orale.','C'),
  T('Quelles habiletés sonores observe-t-on chez les bébés ?','Une audition précoce, la discrimination des sons et des contrastes phonétiques de toutes les langues.'),
  C('L’assimilation intuitive des premiers mots s’établit…','grâce aux cours de musique.|à la fin de la première année.|entre trois et quatre ans.','B'),
  T('Comment les tout-petits élargissent-ils leur langage ?','Grâce aux explications des adultes.'),
  C('Qu’attend-on de leur scolarisation au primaire ?','Qu’ils puissent écrire ce qu’ils savent dire.|Qu’ils aient assimilé des stratégies de communication.|Qu’ils soient passionnés et désireux d’apprendre.','C'),
  TF('La musique développe la solitude chez les tout-petits.','Faux','Elle a un côté rassembleur et aide les enfants en difficulté.'),
  TF('La musique aide les enfants à mieux maîtriser leur environnement.','Vrai','Elle développe la mémoire, la concentration, l’attention, l’écoute et la perception.'),
  TF('Les cours de musique nuisent souvent à leur confiance en eux.','Faux','Les enfants en retirent de la fierté et développent leur estime d’eux-mêmes.'),
  T('Quel rapport une étude établit-elle entre musique et langage ?','Les enfants qui distinguent la hauteur des sons repèrent mieux les rimes, les syllabes et les phonèmes.'),
  TF('L’apprentissage des tout-petits repose notamment sur une répétition ludique.','Vrai','Ils répètent en s’amusant et améliorent ainsi leur prononciation.'),
  C('Que signifie « les enfants qui distinguent davantage de séquences rythmiques segmentent mieux les mots » ?','L’écriture est étayée par la lecture à haute voix.|La segmentation syllabique favorise l’oral.|La discrimination auditive stimule le développement langagier.','C'),
  T('Pourquoi les parents de Thomas sont-ils enchantés ? Donnez deux raisons.','Il emploie des mots appropriés, se fait comprendre dans plusieurs situations et chante tout le temps.'),
  T('Pourquoi la musique améliore-t-elle les performances intellectuelles ?','Elle stimule le langage, les mathématiques et la curiosité, contribuant à la réussite scolaire.'),
  C('Quelle est la conclusion du texte ?','Écouter de la musique renforce la famille.|Représenter une chanson par un dessin fait travailler l’imagination.|Le chant enrichit le vocabulaire.','B')])
 put('reading-mock-5',[
  C('Quelle idée est traitée dans cet article ?','De nouvelles carrières sont proposées aux étudiants.|Les universités développent aussi l’esprit d’entreprendre.|De nombreux étudiants suivent les nouvelles professions.','B'),
  T('Quel succès le statut d’étudiant-entrepreneur connaît-il ?','Il reste modeste : seuls 3 % des 18–24 ans créent une entreprise.'),
  C('Après l’intégration de l’entrepreneuriat à l’université…','les pouvoirs publics l’introduisent au primaire.|les entreprises participantes sont lourdement imposées.|la tendance est d’impliquer aussi les syndicats.','C'),
  T('Comment traiter le manque de contacts des jeunes entrepreneurs ?','Proposer un accompagnement et un mentorat, avec une réduction d’impôt pour les mentors.'),
  C('Quel est l’intérêt pratique du livre blanc ?','Les étudiants peuvent obtenir un financement.|Le plan d’aide est national.|Chaque start-up reçoit au moins 250 000 euros.','A'),
  TF('Les stages des étudiants-entrepreneurs se déroulent en début d’année.','Faux','Les stages de fin d’année sont prévus au printemps, certains étudiants pouvant en être dispensés.'),
  TF('Les grands établissements ont intégré l’entrepreneuriat à leur cursus.','Vrai','Les trente grands sites d’enseignement supérieur se sont engagés à intégrer ces modules.'),
  TF('Plus de la moitié des étudiants formés créent ensuite une entreprise.','Faux','Seule une très petite proportion, environ 1 %, le fait.'),
  T('Quelle condition permet de suivre la formation à l’entrepreneuriat ?','Avoir obtenu le baccalauréat.',['le baccalauréat','avoir obtenu le baccalauréat','baccalauréat','bac']),
  TF('Des dérogations peuvent être accordées aux étudiants-entrepreneurs.','Vrai','Le statut offre des aménagements comparables à ceux des sportifs de haut niveau.'),
  C('Que signifie un projet de micro-activité ?','Un financement sur plusieurs années.|Un programme macroéconomique.|Une action dont la portée est restreinte.','C'),
  T('Comment déposer sa candidature ?','Télécharger le dossier sur Internet, le remplir et le présenter au PEPITE.'),
  T('Quel moyen peut accroître l’intérêt des étudiants pour l’entrepreneuriat ?','Intégrer les modules aux cursus et leur attribuer des crédits comptant pour le diplôme.'),
  T('Comment ont évolué les réactions au plan PEPITE ?','Autrefois difficile à faire accepter, l’entrepreneuriat est désormais mieux admis et ne provoque plus les mêmes oppositions.')])
 put('reading-mock-6',[
  C('Quel est l’objectif principal de cet article ?','Dénoncer une supercherie contre la voiture électrique.|Analyser ses avantages mécaniques.|Présenter la controverse sur la voiture électrique.','C'),
  T('Quel est le but de la voiture électrique ?','Réduire les émissions de gaz à effet de serre et améliorer localement la qualité de l’air.'),
  C('Pourquoi fait-elle l’objet de divergences ?','Elle coûte très cher.|Elle ne rime pas, selon certains, avec écologie.|Elle est désormais incontournable.','B'),
  T('Est-elle réellement écologique du point de vue technologique ?','Il n’existe pas aujourd’hui de voiture entièrement propre : la production et le recyclage ont aussi un impact.'),
  C('Quel avenir semble se dessiner pour les énergies renouvelables ?','Sombre.|Prometteur.|Néfaste.','B'),
  TF('L’étude de l’Ademe ne relève que des défauts.','Faux','Les médias ont surtout repris le négatif, mais l’étude souligne aussi des avantages.'),
  TF('Les émissions de gaz à effet de serre de l’électrique sont encourageantes.','Vrai','En matière de CO₂, l’électrique l’emporte malgré le coût écologique de la production.'),
  TF('L’électrique permet de rouler moins cher et d’être plus autonome en énergie.','Vrai','Le plein coûte moins cher et l’utilisateur peut produire sa propre énergie.'),
  T('Que sous-entend la critique de la voiture électrique ?','La volonté de continuer à utiliser les énergies fossiles.'),
  TF('Plusieurs facteurs constituent encore une lourde charge contre l’électrique.','Faux','Le texte estime qu’il ne reste qu’un élément réellement à charge : la batterie.'),
  T('Quel avenir attend les énergies fossiles ?','Elles seront progressivement supplantées par les énergies renouvelables.'),
  T('La voiture électrique suffit-elle à se libérer des énergies fossiles ?','Non, elle constitue seulement l’une des solutions possibles.'),
  C('Que signifie dans ce contexte « l’année 2015 marque un tournant » ?','Sonner le glas.|Arriver par hasard en même temps.|Laisser son empreinte.','C'),
  T('Citez une ville européenne ambitieuse et un véhicule à l’autonomie prometteuse.','Amsterdam prévoit de multiplier ses bornes ; la QUANT e-Sportlimousine annonce une autonomie de 600 km.')])
 put('reading-mock-1',[
  C('Quel est l’objectif poursuivi par l’auteur ?','Défendre l’école publique.|Réajuster les valeurs sociales de l’école de la République.|Rendre l’éducation porteuse d’un projet de société.','C'),
  T('En quoi le rôle de l’éducation semble-t-il limité dans nos sociétés ?','Elle ne peut pas remplacer tous les manques sociaux.'),
  T('Quelles deux missions de l’école amplifient son malaise ?','Elle est le miroir des problèmes de société et un carrefour accueillant des jeunes en recherche de repères.'),
  C('En France, le débat sur l’éducation est perçu comme…','un phénomène déjà réglé.|un sujet où la passion s’en mêle.|une question sociétale.','C'),
  TF('Les modèles éducatifs connaissent un développement régulier et raisonnable.','Faux','Le texte parle de l’enchevêtrement des modèles éducatifs.'),
  TF('Les changements éducatifs se sont brusquement interrompus peu avant 1968.','Faux','Des changements s’annonçaient bien avant les soubresauts de 1968.'),
  TF('On ne compte pas le nombre de modèles éducatifs depuis cinquante ans.','Faux','L’article distingue trois modèles successifs.'),
  TF('L’instauration des modèles révèle un manque de dialogue constructif.','Vrai','Les changements ont eu lieu sans réel débat sur leurs transformations profondes.'),
  T('Comment qualifie-t-on le modèle éducatif après la Seconde Guerre mondiale ?','Il reste identique au modèle légué par les générations précédentes.'),
  T('Pourquoi ce modèle est-il une réalité partagée ? Citez trois raisons.','Il est conforté par la stabilité de la société, des institutions, des familles et des références morales, spirituelles ou politiques.'),
  TF('Le modèle de l’héritage assimile difficilement la nouveauté.','Vrai','Sa limite réside dans sa difficulté à intégrer le changement et le nouveau.'),
  T('Comment qualifie-t-on la période après les années 1980 ?','Une période dominée par l’individualisme.'),
  C('Quelle devise domine désormais la société française ?','Tout est encore possible.|L’autorité fait loi.|Chacun pour soi.','C'),
  T('Qu’attendent les jeunes aujourd’hui ?','Des propositions fortes et sensées.'),
  T('Pourquoi un bricolage des modèles antérieurs reste-t-il possible ?','On peut recomposer artificiellement les modèles autour de la contestation et de l’individualisme.'),
  T('Pourquoi la succession des anciens modèles ne suffit-elle plus ?','Les jeunes attendent un dialogue clair sur les formes de vie individuelles et collectives adaptées à la nouvelle culture.')])
 put('reading-mock-2',[
  C('Quel est l’objectif principal de ce texte ?','Évaluer les effets de la COP21.|Présenter la portée de la COP21.|Remanier les priorités de la COP21.','B'),
  T('Depuis quand la COP constitue-t-elle une entité internationale ?','Depuis la première conférence organisée à Berlin en 1995.'),
  C('Avec la COP21, un accord climatique…','préétabli sera enfin entériné.|tant espéré sera seulement débattu.|très attendu sera probablement reporté.','A'),
  T('Quel constat le GIEC établit-il ?','L’humanité peut s’adapter à une hausse de 2 °C, mais à 4 °C les dégâts seraient colossaux et irréversibles.'),
  C('Ce constat a été soulevé pour la première fois à la…','COP13.|COP15.|COP16.','A'),
  TF('La COP21 engage tous les pays à partir de 2020.','Vrai','L’accord attendu à Paris doit s’appliquer à cette date pour prendre le relais.'),
  TF('Tous les pays signataires doivent réduire leurs émissions de 20 % avant 2020.','Faux','Cet objectif concerne l’Union européenne ; les objectifs varient selon les pays.'),
  TF('La COP21 est inaugurée par les chefs d’État des pays participants.','Vrai','Les chefs d’État interviennent au début du sommet pour donner une impulsion.'),
  T('Citez deux parties prenantes aux négociations.','Les délégués gouvernementaux, les ONG, les syndicats, les industriels ou les observateurs de la société civile.'),
  T('Résumez trois conditions de concrétisation de la COP21.','Prendre en compte les moyens et responsabilités des États ; organiser l’aide financière Nord-Sud ; investir dans les énergies propres en assurant le développement.'),
  TF('Les préparatifs portent sur les dispositions à adopter par chaque pays.','Vrai','Les 195 États font le point sur les efforts qu’ils sont disposés à faire.'),
  T('Mentionnez un problème survenu au dernier moment.','Des contributions nationales manquent, les échanges sont lents ou les négociateurs n’arrivent pas à finaliser le texte.'),
  C('Que signifie « des propositions à côté de la plaque » ?','Des propositions impossibles à réaliser.|Des propositions hors contexte.|Des propositions envisageables.','B'),
  T('Quel objectif pourrait rendre l’accord plus ambitieux et optimiste ?','Plafonner le réchauffement à 1,5 °C.')])
 put('reading-mock-3',[
  C('Quel est l’objectif principal de ce texte ?','Présenter les abus de la vidéosurveillance.|Affiner les avantages de la vidéosurveillance.|Faire un état des lieux du développement de la vidéosurveillance.','C'),
  T('Qu’est-ce qui explique son développement dans les villes ?','L’idée que les caméras dissuadent les comportements déviants.'),
  C('Les enquêtes sur la vidéosurveillance…','ne montrent aucun lien avec la délinquance.|montrent un lien étroit avec la délinquance.|témoignent d’un rapport particulier avec la délinquance et la criminalité.','C'),
  T('Comment choisit-on les études d’impact ?','On retient des études comparant les mêmes variables avant et après l’intervention, tenant compte du contexte et comparant des groupes traités et non traités.'),
  C('Les études sont organisées selon…','la population choisie.|la portée de l’impact.|le temps de l’élaboration.','B'),
  TF('Les premières études d’impact retenues sont britanniques.','Vrai','Les deux méta-analyses citées, réalisées en 2002 et en 2005, sont britanniques.'),
  TF('Les études poursuivent depuis le début le même objectif.','Vrai','Depuis vingt ans, les décideurs prônent une approche de la criminalité fondée sur des preuves.'),
  TF('En France, l’État assume la responsabilité de ce type d’études.','Vrai','Le ministère de l’Intérieur tient ce rôle en France.'),
  T('La vidéosurveillance a-t-elle partout la même efficacité ?','Non. Son efficacité varie selon les lieux et les délits.'),
  C('Que signifie « la caméra n’est pas un médicament universel » ?','La caméra ne convient pas à tous les cas de figure.|La caméra n’agit qu’à court terme.|La caméra pèse lourd dans les études d’impact.','A'),
  TF('La vidéosurveillance est la solution préférée des personnes interrogées.','Faux','Si on leur donne le choix, elles préfèrent la présence de policiers dans les rues.'),
  T('Quels endroits ont été étudiés en Australie ?','Des zones de bord de mer et quatre gares ferroviaires sur la même ligne.'),
  C('Que dénoncent les opposants à la vidéosurveillance ?','Une action superficielle contre la délinquance.|La violation des libertés individuelles.|La transposition de la réalité.','C'),
  C('Quelle est la conclusion du texte ?','Les caméras suppriment le sentiment d’insécurité.|Les échecs de la vidéosurveillance sont à craindre.|L’apport des politiques n’a pas été identifié.','C')])
